    res['voronoi_attrs'] = [a for a in dir(mm) if 'voronoi' in a.lower()]
    for a in res['voronoi_attrs']:
        res[a] = repr(getattr(mm, a))[:200]
    # menu path
    mmmenu = getattr(mm, 'mmqgis_menu', None)
    if mmmenu:
        def walk(m, prefix):
            out=[]
            for ac in m.actions():
                if ac.menu():
                    out += walk(ac.menu(), prefix+ac.text()+' > ')
                else:
                    out.append((prefix+ac.text(), ac.isEnabled(), ac.isVisible()))
            return out
        res['items'] = [i for i in walk(mmmenu,'') if 'voronoi' in i[0].lower()]
result = res"}
